def solve():
    solutions = []
    for c in range(1, 10):
        target = 6**c - 1
        for b in range(1, 10):
            rem = target - 3**b
            if rem > 0:
                # Check if rem is a power of 2
                if (rem & (rem - 1)) == 0 and rem > 0:
                    a = rem.bit_length() - 1
                    B = 2**a + 1
                    T = 3**b + 1
                    S = 6**c + 1
                    solutions.append((B, T, S))
            else:
                break
    return solutions

